"""The 15 MCQs + writing prompt of Krea's own sample test, solved here. (Krea publishes no key.)"""
S = "Problem-Solving"; C = "Critical Thinking & Verbal Ability"; N = "Numeric Reasoning"
OFF = [
 (S, "A, B, C, D, E, F and G sit along a wall facing North. C is immediately to the right of D. B sits at an extreme end and has E as a neighbour. G is between E and F. D sits third from one of the ends. Who sits in the middle?", ["Fanny", "Gabriel", "Dereck", "Emmy"], 0,
  "‘E–G–F’ must be consecutive and B (at an end) touches E, so one end reads <b>B E G F</b> (positions 1–4). D and C are adjacent with C to D's right, and D is third from an end; the only place is positions 5–6 (D is 3rd from the right end). A takes 7. Order: B E G F D C A. The 4th person is <b>F (Fanny)</b>. The mirror arrangement (B at the right end) forces D into position 3 with C at 4, which is already taken, so the answer is unique."),
 (S, "If A G C I E is written as C I E K G and F L H N J is written as H N J P L, how is L Z P W X B coded?", ["MAQXYC", "MBQXYD", "NBRYZD", "None of These"], 2,
  "A→C, G→I, C→E, I→K, E→G: each letter moves <b>+2</b>. Apply: L→N, Z→B, P→R, W→Y, X→Z, B→D = <b>NBRYZD</b>."),
 (S, "If Jenifer's father is the grandfather of Hillary, how is Jenifer's mother related to Hillary?", ["Sister", "Mother", "Grandmother", "Aunt"], 2,
  "Jenifer's father is Hillary's grandfather; his wife, Jenifer's mother, is therefore Hillary's <b>grandmother</b> (taking the usual reading that they are the parents of Jenifer). Jenifer herself is Hillary's mother or aunt, so ‘Mother’ and ‘Aunt’ are wrong for Jenifer's <i>mother</i>."),
 (S, "In a certain code FRENCH is written as FQEMCG. How is JULY written?", ["JVLZ", "JTLX", "IUKY", "IULX"], 1,
  "F→F (0), R→Q (−1), E→E (0), N→M (−1), C→C (0), H→G (−1): shifts alternate 0, −1. JULY: J(0)=J, U(−1)=T, L(0)=L, Y(−1)=X → <b>JTLX</b>."),
 (S, "Ana starts from point X and walks 5 km west, then turns left and walks 2 km. She again turns left and walks 7 km. In which direction is she from X?", ["North-west", "South-west", "South-east", "North-east"], 2,
  "West 5 → x = −5. Facing west, a left turn points south: 2 km → y = −2. Facing south, a left turn points east: 7 km → x = +2. Final (+2, −2): <b>south-east</b> of X."),
 (C, "Alex bought a phone in country Y. Inserting a SIM gave ‘No sim inserted’. Only Network ABC's SIM worked. Which conclusion can be made?", ["‘No sim inserted’ is an issue Alex faced with all networks' SIMs.", "All phones sold in country Y have issues.", "Network ABC is the best network, which is why its SIM worked.", "None of the above."], 3,
  "ABC's SIM worked, so the error did not appear with all SIMs (A false). One phone cannot show anything about all phones in Y (B). The facts say nothing about ‘best’ (C). <b>None of the above</b>."),
 (C, "‘There are enough problems to speak about, one of them is that people cannot find friends that ideal, but are they themselves the ideal friend.’ Choose the option that correctly rephrases the underlined part (the paper's underlining is not visible in the published PDF).", ["One of them being that people cannot find ideal friends", "One of them is that people cannot find friends which are ideal", "One of them is people cannot found friends ideal", "And one of them being that people can find friends, but not the ideal", "No error"], 1,
  "<b>Caveat: Krea publishes no key and the underlined portion is not shown, so this is our best judgement.</b> The original joins two independent clauses with a comma (a comma splice) and uses the awkward ‘friends that ideal’. Option B repairs the grammar of the clause without changing its meaning; A leaves a fragment, C has ‘found’ for ‘find’, and D reverses the meaning. Treat B as the most defensible choice, but do not rely on it as an official answer."),
 (C, "Identify the error: ‘The amount of hard work put in this project is immense.’", ["immense", "hard work", "amount", "No error"], 3,
  "‘Amount’ is correct for an uncountable noun (‘hard work’), and ‘immense’ agrees with it. The only slip is the preposition (‘put <i>into</i>’), which is not one of the options, so of the choices offered the answer is <b>No error</b>. (Krea publishes no key; this is our reading.)"),
 (C, "Prolonged exposure to ultraviolet rays increases the chances of skin cancer. TV screens, computer monitors and water purifiers also emit UV rays. Which conclusion is best supported?", ["Prolonged exposure to UV is the primary cause of skin cancer.", "TVs, monitors and water purifiers thin the ozone layer.", "Certain devices of our day-to-day life can cause skin cancer.", "A person with skin cancer must have been exposed to UV from those devices."], 2,
  "UV raises skin-cancer risk; these devices emit UV; so they <i>can</i> contribute. A over-reaches (‘primary’), B brings in the ozone layer, D says ‘must’. The hedged conclusion <b>C</b> is the only one fully supported."),
 (C, "‘If the media and judiciary had not unearthed and corrected the corrupt, the society would have taken corruption as no ______.’", ["Malaise", "Inquest", "Dullard", "Chortle"], 0,
  "Malaise = a general sense of something being wrong. ‘Taken corruption as no malaise’ = not regarded it as a problem. An inquest is an investigation, a dullard a stupid person, a chortle a chuckle: none fits."),
 (N, "An institute has 720 students. Today 144 are on leave. What percentage are present?", ["20%", "51%", "68%", "80%"], 3, "Present = 720 − 144 = 576; 576/720 × 100 = <b>80%</b>. (20% is the share on leave.)"),
 (N, "A pizza costs $50 and a burger $20. Find the ratio of the cost of a burger to that of a pizza.", ["2:5", "3:5", "1:5", "4:5"], 0, "Burger : pizza = 20 : 50 = <b>2 : 5</b> (order matters: burger first)."),
 (N, "A briefcase is sold at a profit of 10%. If its cost price had been 5% less and it was sold for ₹7 more, the gain would have been 20%. Find the cost price.", ["₹175", "₹200", "₹225", "₹160"], 0,
  "Let CP = x. Sold at 1.10x. New CP = 0.95x, new SP = 1.20 × 0.95x = 1.14x. This SP is ₹7 more: 1.14x − 1.10x = 7 → 0.04x = 7 → x = <b>₹175</b>."),
 (N, "What is the ratio of a father's age to his son's age if they are 35 and 5?", ["5:1", "6:1", "7:1", "1:7"], 2, "35 : 5 = <b>7 : 1</b>."),
 (N, "UCUCU Bank's revenues are 20% more than Lena Bank's. By what percent are Lena Bank's revenues less than UCUCU's?", ["22.5%", "20%", "25%", "16.67%"], 3,
  "Lena = 100, UCUCU = 120. Lena is less by 20/120 × 100 = <b>16.67%</b> – the base is now UCUCU's revenue."),
]
